// This file is generated by AI.

// 文本预处理中间格式的 Monaco 适配层: 注册语言、高亮、格式化, 以及 IEditorHost 实现。
// 与编辑器 UI 解耦, 通过注入 Monaco 实例避免重复依赖。

import type * as Monaco from 'monaco-editor';

import { formatIntermediate, type IEditorHost } from 'webgal-novel-preprocess';

/** 中间格式语言 id (区别于场景文件的 `webgal`)。 */
export const NOVEL_LANGUAGE_ID = 'webgal-novel';

const novelMonarch: Monaco.languages.IMonarchLanguage = {
  // 正文 (对话内容 / 纯文本) 统一为字符串色, 前缀分别着色。
  defaultToken: 'string',
  tokenizer: {
    root: [
      // 注释行 (原句 / 警告)
      [/^;.*/, 'comment'],
      // 未分配对话占位符 %
      [/^%/, 'keyword'],
      // 已分配说话者 名称 (直到冒号前)
      [/^[^:]+(?=:)/, 'type'],
      // 冒号 (旁白 `:` 与说话者/占位符后的 `:`)
      [/:/, 'operator'],
    ],
  },
};

/** 注册中间格式语言 (高亮 + 格式化)。应用启动时调用一次。 */
export function registerNovelLanguage(monaco: typeof Monaco): void {
  monaco.languages.register({ id: NOVEL_LANGUAGE_ID });
  monaco.languages.setLanguageConfiguration(NOVEL_LANGUAGE_ID, {
    comments: { lineComment: ';' },
  });
  monaco.languages.setMonarchTokensProvider(NOVEL_LANGUAGE_ID, novelMonarch);
  monaco.languages.registerDocumentFormattingEditProvider(NOVEL_LANGUAGE_ID, {
    provideDocumentFormattingEdits: (model) => [
      { range: model.getFullModelRange(), text: formatIntermediate(model.getValue()) },
    ],
  });
}

/** 创建中间格式文档对应的 Monaco model (内存 model, 非磁盘文件; 已存在则复用)。 */
export function createNovelModel(monaco: typeof Monaco, uri: string, content = ''): Monaco.editor.ITextModel {
  const parsed = monaco.Uri.parse(uri);
  return monaco.editor.getModel(parsed) ?? monaco.editor.createModel(content, NOVEL_LANGUAGE_ID, parsed);
}

/** 将 Monaco 编辑器包装为 IEditorHost, 供 NovelSession 驱动。 */
export function createEditorHost(monaco: typeof Monaco, editor: Monaco.editor.IStandaloneCodeEditor): IEditorHost {
  return {
    getContent: () => editor.getValue(),
    setContent: (text) => {
      if (editor.getValue() !== text) editor.setValue(text);
    },
    setReadOnly: (readOnly) => editor.updateOptions({ readOnly }),
    replaceLine: (line, text) => {
      const model = editor.getModel();
      if (!model || line >= model.getLineCount()) return;
      const range = new monaco.Range(line + 1, 1, line + 1, model.getLineMaxColumn(line + 1));
      // 用 model 级操作 (绕过编辑器 readOnly 限制)。
      model.pushEditOperations([], [{ range, text, forceMoveMarkers: true }], () => null);
    },
    selectLines: (start, end) => {
      const model = editor.getModel();
      if (!model) return;
      const endCol = model.getLineMaxColumn(end + 1);
      editor.setSelection(new monaco.Selection(start + 1, 1, end + 1, endCol));
      editor.revealLineInCenterIfOutsideViewport(start + 1);
    },
    setCursorLine: (line) => editor.setPosition({ lineNumber: line + 1, column: 1 }),
    onContentChange: (cb) => {
      const sub = editor.onDidChangeModelContent(() => cb(editor.getValue()));
      return () => sub.dispose();
    },
    onCursorLine: (cb) => {
      const sub = editor.onDidChangeCursorPosition((e) => cb(e.position.lineNumber - 1));
      return () => sub.dispose();
    },
    onKey: (cb) => {
      const dom = editor.getDomNode();
      if (!dom) return () => {};
      const handler = (ev: KeyboardEvent) => {
        if (cb(ev.key)) ev.preventDefault();
      };
      dom.addEventListener('keydown', handler, true);
      return () => dom.removeEventListener('keydown', handler, true);
    },
    focus: () => editor.focus(),
  };
}
